function hire(s){s.workers??=[];if(s.workers.length>=capacity(s))return {error:'Нет свободного жилья. Постройте или завершите дом.'};if((s.cookedMeat||0)+(s.cookedFish||0)+(s.cookedVegetables||0)<3)return {error:'Нужно 3 порции приготовленной еды.'};let home=s.buildings.find(b=>b.type==='house'&&C.ready(b)),spawn=null;for(let y=home.y-1;y<=home.y+2;y++)for(let x=home.x-1;x<=home.x+2;x++)if(!spawn&&C.walkable(s,x,y))spawn={x:x+.5,y:y+.5};if(!spawn)return {error:'У дома нет свободного выхода. Освободите проход.'};let remaining=3;for(let kind of ['cookedMeat','cookedFish','cookedVegetables']){let amount=Math.min(s[kind]||0,remaining);s[kind]=(s[kind]||0)-amount;remaining-=amount;}let w={id:'worker-'+Date.now()+'-'+s.workers.length,name:names[s.workers.length%names.length]+(s.workers.length>=names.length?' '+(s.workers.length+1):''),...spawn,role:'idle',status:'Отдыхает',route:[],target:null,work:0,retry:0,face:1,moving:false,energy:100,hunger:100,thirst:100,need:null};s.workers.push(w);return {worker:w}}
