 if(w.work<(w.role==='fish'?(s.rodLevel===2?6:9):3))return;
 w.work=0;w.energy=Math.max(0,w.energy-3);w.hunger=Math.max(0,w.hunger-.7);w.thirst=Math.max(0,w.thirst-1);
 if(w.role==='fish'){s.fish++;s.stats.fish++;events.push({kind:'splash',x:w.x,y:w.y,resource:'fish',amount:1});return}
 let result;{let kind=s.meat>0?'meat':s.fish>0?'fish':'vegetables';result=C.cook(s,t.id,kind,Math.min(3,kind==='vegetables'?Math.max(0,s.vegetables):3))}
